'use strict';
let adultState=null;
const friendlyNames={tshirt:'T-shirt',paintbrush:'paintbrush',toothbrush:'toothbrush',trousers:'trousers',gloves:'gloves',wateringcan:'watering can',emptycup:'empty cup',fullcup:'full cup',blocks:'blocks',bowl:'bowl',cloth:'cloth',banana:'banana',tomato:'tomato',bee:'bee'};
const nameOf=id=>friendlyNames[id]||id;
function adultSupportBanner(key){return `<aside class="adult-support" role="note"><span class="adult-support-icon" aria-hidden="true">● ●</span><div><b>Adult support required throughout this course</b><span>${key==='sounds'?'An adult must supply the spoken-English words and speech sounds. The app does not produce audio.':'Stay with the child. Give each prompt using speech, sign, or their established communication system.'}</span></div></aside>`;}
function makeAdultTask(key,index,round){
 const d=adultCourseInfo[key].games[index],r=round%3;let t={mode:'choice',reference:[],options:[],answer:[],childPrompt:'Explore the pictures with your grown-up.',explanation:d.skill};
 const options=(correct,others,prompt,teach='')=>{t.options=shuffle([{id:'answer',picture:correct},...others.map((picture,i)=>({id:'other'+i,picture}))]);t.answer=['answer'];t.adult=prompt;t.teach=teach;};
 const attr=(a,value,object)=>({type:'attribute',attr:a,value,object});
 if(key==='words'){
  if(d.mode==='nouns'){const id=d.items[r];options(id,d.items.filter(x=>x!==id),`Show me the ${nameOf(id)}.`,`Before asking, name each pictured object: ${d.items.map(nameOf).join(', ')}. Point to each as you model its name.`);}
  if(d.mode==='full'){const word=r===1?'empty':'full';options(attr('full',word),[attr('full',word==='full'?'empty':'full')],`Show me the ${word} cup.`,'Use real empty and filled cups first. Model “full” and “empty,” then compare the pictures.');}
  if(d.mode==='size'){const word=r===1?'big':'small';options(attr('size',word,'ball'),[attr('size',word==='big'?'small':'big','ball')],`Show me the ${word} ball.`,'Model both size words with the two pictures. Size is relative to the other pictured ball.');}
  if(d.mode==='wet'){const word=r===1?'dry':'wet';options(attr('wet',word),[attr('wet',word==='wet'?'dry':'wet')],`Show me the ${word} boot.`,'Explain that the blue drops stand for water. Compare a safely damp cloth with a dry one away from the screen.');}
  if(d.mode==='open'){const word=r===1?'closed':'open';options(attr('open',word),[attr('open',word==='open'?'closed':'open')],`Show me the ${word} box.`,'Demonstrate opening and closing a real box before asking about the pictures.');}
  if(d.mode==='quantity'){const value=r===1?3:1;options(attr('quantity',value,'ball'),[attr('quantity',value===1?3:1,'ball')],value===1?'Show me one ball.':'Show me several balls.','Model “one” and “several” with real objects. This is language practice, not a counting test.');}
  if(d.mode==='actions'){const action=d.items[r];options({type:'actor',action},d.items.filter(a=>a!==action).map(action=>({type:'actor',action})),`Show me ${action==='sleep'?'sleeping':action==='sit'?'sitting':action==='carry'?'carrying':action==='brush'?'brushing':action+'ing'}.`,'Demonstrate and name each action with toys or gestures first. The drawings are simplified; help interpret them.');}
  if(d.mode==='function'){const a=[['cup','What can we drink from?'],['coat','What can help keep us warm?'],['brush','What can clean these boots?']][r];options(a[0],['ball','book'],a[1],'Explain this use first, with a real object if available. Accept a sensible alternative in real life.');}
  if(d.mode==='partners'){const a=[['spoon','bowl'],['key','lock'],['wateringcan','flower']][r];t.reference=[a[0]];options(a[1],['ball','hat'],`Which picture goes with the ${nameOf(a[0])} in our example?`,`Model the connection between ${nameOf(a[0])} and ${nameOf(a[1])}. Explain or demonstrate how they work together.`);}
  if(d.mode==='category'){const a=[['coat','clothing'],['apple','food'],['ball','a toy']][r];options(a[0],['key','clock'],`Show me ${a[1]==='a toy'?'a toy':'something that is '+a[1]}.`,`Give examples of ${a[1]} first. Categories depend on context; explain the intended group.`);}
  if(d.mode==='shape'){const value=['round','square','triangle'][r],word={round:'round',square:'square',triangle:'triangular'}[value];options(attr('shape',value),['round','square','triangle'].filter(v=>v!==value).map(v=>attr('shape',v)),`Show me the ${word} shape.`,'Name and demonstrate the three shapes before asking.');}
  if(d.mode==='negative'){const word=r===1?'full':'empty';options(attr('full',word==='empty'?'full':'empty'),[attr('full',word)],`Show me the cup that is not ${word}.`,'First teach the positive descriptions. Explain “not” with familiar examples and a contrast.');}
  if(d.mode==='newexample'){const id=['cup','shoe','coat'][r];t.reference=[id];options({icon:id,variant:3},['ball','key'],`Find another picture of a ${nameOf(id)}.`,'Name the model picture. Explain that a different drawing can represent the same kind of object.');}
  if(d.mode==='attributes'){const size=r===1?'big':'small',full=r!==2;options({type:'attribute',attr:'two',size,full},[{type:'attribute',attr:'two',size:size==='small'?'big':'small',full},{type:'attribute',attr:'two',size,full:!full}],`Show me the ${size}, ${full?'full':'empty'} cup.`,'Model each word separately first. Then combine the two clues. Repeat or simplify if needed.');}
 }
 if(key==='sentences'){
  let mode=d.mode;if(mode==='review')mode=['chase','position','negative'][r];
  const actors=['bear','rabbit','cat'],actor=actors[r],other=actors[(r+1)%3];
  const act=(action,object='ball',who=actor)=>({type:'actor',actor:who,action,object});
  const roles=(a,b,action,object='ball')=>({type:'roles',actor:a,patient:b,action,object,reverse:r===1});
  const position=(p,reference='box')=>({type:'position',object:'ball',reference,position:p});
  if(mode==='verb'){const verb=['sleep','sit','jump'][r];options(act(verb),['sleep','sit','jump'].filter(v=>v!==verb).map(v=>act(v)),`The ${actor} is ${verb==='sleep'?'sleeping':verb==='sit'?'sitting':'jumping'}. Show me.`,'Name the character and demonstrate each action before asking.');}
  if(mode==='subject'){options(act('jump'),actors.filter(a=>a!==actor).map(a=>act('jump','ball',a)),`The ${actor} is jumping. Show me.`,'Name the bear, rabbit, and cat. All three pictures show the same action; listen for who does it.');}
  if(mode==='object'){const object=['ball','car','box'][r];options(act('push',object),['ball','car','box'].filter(o=>o!==object).map(o=>act('push',o)),`The ${actor} pushes the ${object}. Show me.`,'Name the objects, then act out pushing with a toy.');}
  if(['chase','follow','wash','brush'].includes(mode)){const a=mode==='chase'?['cat','dog'][r%2]:actor,b=mode==='chase'?['cat','dog'][(r+1)%2]:other;const phrase={chase:'chases',follow:'follows',wash:'washes',brush:'brushes'}[mode];options(roles(a,b,mode),[roles(b,a,mode)],`The ${a} ${phrase} the ${b}. Show me.`,`Name both characters. Notice who reaches out or follows behind. Act out “${a} ${phrase} ${b}” and the reverse with toys. These stylized scenes need explanation.`);}
  if(mode==='give'||mode==='giveobject'){const object=mode==='give'?'ball':['book','cup','ball'][r];options(roles(actor,other,'give',object),[roles(other,actor,'give',object),roles(actor,other,'give',object==='ball'?'book':'ball')],`The ${actor} gives the ${object} to the ${other}. Show me.`,'Name both characters. Demonstrate giving. The giver is reaching out with the object.');}
  if(mode==='position'){const p=['in','on','under'][r];options(position(p),['in','on','under'].filter(x=>x!==p).map(x=>position(x)),`The ball is ${p} the box. Show me.`,'Demonstrate each position using a real ball and box. The partially covered ball represents “in.”');}
  if(mode==='treeposition'){const p=['beside','behind','front'][r],word=p==='front'?'in front of':p;options(position(p,'tree'),['beside','behind','front'].filter(x=>x!==p).map(x=>position(x,'tree')),`The ball is ${word} the tree. Show me.`,'Use a toy tree or another familiar upright object. Demonstrate the three positions. “Behind” is shown partly hidden.');}
  if(mode==='chairposition'){const p=['on','under','beside'][r];options(position(p,'chair'),['on','under','beside'].filter(x=>x!==p).map(x=>position(x,'chair')),`The ball is ${p} the chair. Show me.`,'Demonstrate with a chair and a suitable object before using pictures.');}
  if(mode==='plural'){const n=r===1?3:1;options(attr('quantity',n,'ball'),[attr('quantity',n===1?3:1,'ball')],n===1?'There is a ball. Show me.':'There are balls. Show me.','Model the singular/plural contrast in the child’s language. No counting response is needed.');}
  if(mode==='attributes'){const size=r===1?'big':'small',full=r!==2;options({type:'attribute',attr:'two',size,full},[{type:'attribute',attr:'two',size:size==='small'?'big':'small',full},{type:'attribute',attr:'two',size,full:!full}],`The cup is ${size} and ${full?'full':'empty'}. Show me.`,'Teach each descriptive word separately first, then combine them.');}
  if(mode==='negative'){const holding=r!==1;options(act(holding?'hold':'nothold','cup'),[act(holding?'nothold':'hold','cup')],`The ${actor} is ${holding?'':'not '}holding a cup. Show me.`,'Model holding versus not holding. Make the negative word clear without turning the task into a speed test.');}
  if(mode==='pushpull'){const action=r===1?'pull':'push';options(act(action,'car'),[act(action==='push'?'pull':'push','car')],`The ${actor} is ${action==='push'?'pushing':'pulling'} the car. Show me.`,'Demonstrate both actions with a toy car. The character pulls with a rope or reaches out to push.');}
  if(mode==='instructions'){const ids=[['cup','spoon','ball'],['hat','coat','key'],['book','ball','cup']][r];t.mode='order';t.options=shuffle(ids.map(id=>({id,picture:id})));t.answer=ids.slice(0,2);t.adult=`First tap the ${ids[0]}, then tap the ${ids[1]}.`;t.teach='Name all three pictures. Model “first…then…” with two different practice objects. Repeat the full instruction if useful.';t.childPrompt='Listen to your adult. Choose two pictures in order.';}
  if(mode==='beforeafter'){const first=act('wash'),last=act('sleep');const seq=(a,b)=>({type:'sequence',items:[a,b]});options(seq(first,last),[seq(last,first)],r===1?`The ${actor} sleeps after washing. Show me the order.`:`Before the ${actor} sleeps, the ${actor} washes. Show me the order.`,'Explain “before” and “after” using a familiar real routine. The arrow shows time order from left to right.');}
  if(mode==='because'){const a=[['umbrella','rain','The character uses an umbrella because it is raining.'],['coat','snow','The character wears a warm coat because it is cold and snowy.'],['lamp','dark','The character turns on a lamp because the room is dark.']][r];t.reference=[a[0]];options(a[1],['sun','ball'].filter(x=>x!==a[1]),a[2]+' Show me the reason.','Act out or explain the cause. Ask for the stated reason, not every possible real-world reason.');}
 }
 if(key==='sounds'){
  let mode=d.mode;if(mode==='review')mode=['phonemeblend','phonemes','final'][r];const item=d.items[r];
  const namedOptions=(answer,others,prompt)=>options(answer,others,prompt,'Name each picture in your usual pronunciation before the sound task. Use the exact intended word; do not substitute a synonym.');
  if(mode==='syllables'||mode==='phonemes'){const [id,count,parts]=item;t.mode='counter';t.reference=[id];t.answer=[count];t.options=[];t.adult=mode==='syllables'?`Say “${id}.” Model its spoken parts: ${parts}. Ask: “Tap one counter for each spoken beat.”`:`Say “${id}.” Model its individual sounds: ${parts}. Ask: “Use one counter for each sound.”`;t.teach=mode==='syllables'?'Demonstrate with claps or counters. These counts use the illustrated English examples; adapt or skip if your pronunciation differs.':'Count phonemes, not letters. “sh” in shoe is one sound; the vowel “oo” is one sound. Use pure sounds, without adding “uh.”';t.childPrompt='Tap counters with your adult, then check.';t.explanation=`In this example, ${id} has ${count} ${mode==='syllables'?'syllable'+(count===1?'':'s'):'speech sounds'}.`;}
  if(mode==='syllableblend'){const [id,parts]=item;namedOptions(id,['cup','ball'],`Say the spoken syllables with short pauses: ${parts}. Ask: “Which word do those parts make?”`);t.reference=[];}
  if(mode==='syllablechoice'){const [answer,...others]=item;namedOptions(answer,others,'Name the pictures. Ask: “Which word has one spoken beat?”');}
  if(mode==='rhyme'){const [model,answer,...others]=item;t.reference=[model];namedOptions(answer,others,`Say “${model}.” Name all choices. Ask: “Which word rhymes with ${model}?”`);}
  if(mode==='rhymeodd'){const [a,b,answer]=item;namedOptions(answer,[a,b],`Say “${a}, ${b}, ${answer}.” Model the rhyme in ${a} and ${b}. Ask: “Which word does not rhyme with those two?”`);}
  if(mode==='rhymeyes'){const [a,b,yes]=item;t.reference=[a,b];t.options=shuffle([{id:'yes',picture:{type:'yesno',value:true}},{id:'no',picture:{type:'yesno',value:false}}]);t.answer=[yes?'yes':'no'];t.adult=`Say “${a}, ${b}.” Ask: “Do these words rhyme?”`;t.teach='Model the yes/check and no/cross response symbols first. Repeat the words naturally, emphasizing the shared ending during teaching.';t.explanation=yes?'These two spoken words rhyme in this English example.':'These two spoken words do not rhyme in this example.';}
  if(mode==='initial'||mode==='final'){const [id,sound]=item;const pool=mode==='final'?['cup','hat','sun']:['sun','moon','ball','cup','tree','hat'];const others=pool.filter(x=>x!==id&&!(mode==='initial'&&id==='tree'&&x==='hat')).slice(0,2);namedOptions(id,others,`Say the ${mode==='initial'?'first':'last'} speech sound ${sound}, not its letter name. Ask: “Which word ${mode==='initial'?'starts':'ends'} with that sound?”`);}
  if(mode==='initialmatch'||mode==='finalmatch'){const [model,answer,...others]=item;t.reference=[model];namedOptions(answer,others,`Name all pictures. Ask: “Which word has the same ${mode==='initialmatch'?'first':'last'} sound as ${model}?”`);}
  if(mode==='initialodd'){const [a,b,answer]=item;namedOptions(answer,[a,b],`Name “${a}, ${b}, ${answer}.” Ask: “Which word starts with a different sound?”`);}
  if(mode==='phonemeblend'){const [id,parts]=item;namedOptions(id,['coat','ball'].filter(x=>x!==id),`Say the separate speech sounds ${parts}. Ask: “Which word do those sounds make?”`);t.teach+=' Use the sound labels as adult directions, not as words to read to the child. Give only each intended speech sound.';}
  if(mode==='review'&&r===2)t.explanation='Revisit one familiar sound task.';
 }
 if(key==='sounds')t.teach+=' Sound key: “vowel in sun/hat/key/shoe” means give just that vowel sound, not those explanatory words. /sh/ is the first sound in shoe. Do not say letter names or add “uh” to consonants. Adapt or skip examples if your pronunciation differs.';
 if(!t.adult||!t.answer.length)throw new Error(`Missing adult task ${key}/${index}/${round}`);
 return t;
}
function adultIntro(index){const key=activeLearningCourse,c=adultCourseInfo[key],d=c.games[index];adultState={index,round:0,independent:0,hints:0,seed:nextPictureVisit(key,index)};learningState={index};const example=makeAdultTask(key,index,0,adultState.seed);learningShell(`<span class="eyebrow">LEARN TOGETHER</span><h1>${d.title}</h1><p>${d.skill}</p><div class="game-stage"><div class="adult-demo-picture">${adultPicture(example.reference[0]||example.options[0]?.picture||d.object)}</div><div class="adult-instructions"><h3>Before you begin</h3><p>${example.teach}</p><p>${key==='sounds'?'Say the English words and sounds yourself. The child can point or tap; speech is not required.':'Use speech, sign, or the child’s established AAC system. Model the meaning before asking for a choice.'}</p><p><b>Stay with the child for every round.</b> The app supplies no voice. Repeat, demonstrate, simplify, or skip when needed.</p></div><button class="primary" id="adultBegin">Start together with an adult →</button></div><div class="learning-note"><b>Try it away from the screen.</b> ${d.exercise}</div>`);document.querySelector('#adultBegin').onclick=adultPlay;}
function adultPlay(){const s=adultState;Object.assign(s,makeAdultTask(activeLearningCourse,s.index,s.round,s.seed),{ready:true,answered:false,missed:false,hinted:false,count:0,selected:[]});renderAdultTask('');window.scrollTo({top:0,behavior:'instant'});}
function renderAdultTask(message){const s=adultState,d=adultCourseInfo[activeLearningCourse].games[s.index];const focus=document.activeElement;let restore=focus?.dataset.adultChoice!==undefined?`[data-adult-choice="${focus.dataset.adultChoice}"]`:focus?.id&&['adultAdd','adultRemove','adultCheck','adultHint','adultClear'].includes(focus.id)?'#'+focus.id:null;
 let body=s.reference.length?`<div class="adult-reference">${s.reference.map(p=>`<div class="story-frame">${adultPicture(p)}</div>`).join('')}</div>`:'';
 if(s.mode==='counter')body+=`<div class="sound-counters" role="group" aria-label="${s.count} counters selected">${Array.from({length:6},(_,i)=>`<span class="sound-counter ${i<s.count?'filled':''}" aria-hidden="true"></span>`).join('')}</div><div class="counter-controls"><button class="secondary" id="adultRemove" aria-label="Remove one counter" ${!s.ready||s.answered||s.count===0?'disabled':''}>−</button><button class="primary" id="adultAdd" aria-label="Add one counter" ${!s.ready||s.answered||s.count===6?'disabled':''}>＋ Add a counter</button></div>`;
 else {if(s.mode==='order')body+=`<div class="adult-order-slots">${[0,1].map(i=>`<div class="story-frame">${s.selected[i]===undefined?'<span class="empty-order">＋</span>':adultPicture(s.options.find(o=>o.id===s.selected[i]).picture)}<small>${i+1}</small></div>`).join('<span class="strip-arrow" aria-hidden="true">→</span>')}</div>`;body+=`<div class="learning-options adult-options">${s.options.map((o,i)=>`<button class="learning-option ${s.selected.includes(o.id)?'selected':''} ${s.hinted&&s.answer.includes(o.id)?'hinted':''} ${s.answered&&s.answer.includes(o.id)?'correct':''}" data-adult-choice="${i}" aria-label="Choose picture ${i+1}" ${!s.ready||s.answered||(s.mode==='order'&&s.selected.includes(o.id))?'disabled':''}>${adultPicture(o.picture,s.round%3)}</button>`).join('')}</div>`;}
 learningShell(`<span class="eyebrow">${adultCourseInfo[activeLearningCourse].subtitle.toUpperCase()}</span><h1>${d.title}</h1><p>${s.childPrompt}</p><div class="game-stage adult-stage">${body}<div class="feedback" role="status" aria-live="polite">${message}</div><div class="game-controls"><button class="secondary" id="adultHint" ${s.answered?'hidden':''} ${!s.ready?'disabled':''}>Show a teaching clue</button>${s.mode==='counter'||s.mode==='order'?`<button class="secondary" id="adultClear" ${s.answered?'hidden':''} ${!s.ready?'disabled':''}>Clear ↶</button><button class="primary" id="adultCheck" ${s.answered?'hidden':''} ${!s.ready?'disabled':''}>Check ✓</button>`:''}<button class="primary" id="adultNext" ${s.answered?'':'hidden'}>${s.round===2?'Finish game →':'Next round →'}</button></div>${s.answered?`<p class="outcome-explanation">${s.explanation}</p>`:''}</div><div class="play-top"><span class="micro">Round ${s.round+1} of 3 · Adult-led practice</span><div class="round-dots" aria-hidden="true">${[0,1,2].map(i=>`<i class="${i<s.round?'done':i===s.round?'current':''}"></i>`).join('')}</div></div><details class="learning-note"><summary>Try it away from the screen</summary><p>${d.exercise}</p></details>`,true);
 document.querySelectorAll('[data-adult-choice]').forEach(b=>b.onclick=()=>adultChoose(+b.dataset.adultChoice));
 const add=document.querySelector('#adultAdd'),remove=document.querySelector('#adultRemove'),check=document.querySelector('#adultCheck'),clear=document.querySelector('#adultClear');if(add)add.onclick=()=>adultCounter(1);if(remove)remove.onclick=()=>adultCounter(-1);if(check)check.onclick=adultCheck;if(clear)clear.onclick=()=>{if(!s.ready||s.answered)return;s.count=0;s.selected=[];renderAdultTask('A fresh try. Ask your adult to repeat the prompt if useful.');};document.querySelector('#adultHint').onclick=adultHint;document.querySelector('#adultNext').onclick=()=>{if(!s.answered)return;s.round++;s.round<3?adultPlay():adultFinish();};
 if(restore){const b=document.querySelector(restore);if(b&&!b.disabled)b.focus();}
}
function adultChoose(i){const s=adultState;if(!s.ready||s.answered)return;const o=s.options[i];if(s.mode==='order'){if(!s.selected.includes(o.id)&&s.selected.length<2)s.selected.push(o.id);renderAdultTask('Check the two choices in order.');return}if(s.answer.includes(o.id)){adultSuccess();return}s.missed=true;renderAdultTask('Let’s explore that meaning or sound again with your adult.');}
function adultCounter(delta){const s=adultState;if(!s.ready||s.answered)return;s.count=Math.max(0,Math.min(6,s.count+delta));renderAdultTask('Your adult can repeat the word or sounds. Check when you are ready.');}
function adultCheck(){const s=adultState;if(!s.ready||s.answered)return;const match=s.mode==='counter'?s.count===s.answer[0]:s.selected.length===s.answer.length&&s.answer.every((id,i)=>s.selected[i]===id);if(match)adultSuccess();else{s.missed=true;renderAdultTask('Try it together again. Your adult can model the steps.');}}
function adultHint(){const s=adultState;if(!s.ready||s.answered)return;if(!s.hinted){s.hinted=true;s.hints++}if(s.mode==='counter')s.count=s.answer[0];if(s.mode==='order')s.selected=[...s.answer];renderAdultTask('Here is a teaching clue. Ask your adult to explain or model it.');}
function adultSuccess(){const s=adultState;if(s.answered)return;s.answered=true;if(!s.missed&&!s.hinted)s.independent++;renderAdultTask('✓ You explored this together!');document.querySelector('#adultNext').focus();}
function adultFinish(){const s=adultState,key=activeLearningCourse,d=adultCourseInfo[key].games[s.index];learningProgress[key]??={};learningProgress[key][s.index]={complete:true,independent:s.independent,hints:s.hints,adultSupported:true,date:new Date().toISOString()};persistLearning();learningShell(`<span class="eyebrow">LEARNED TOGETHER</span><div class="success-icon" aria-hidden="true">✳</div><h1>You explored ${d.title.toLowerCase()}!</h1><p>Three rounds with an adult’s language or sound model.</p><div class="completion-stat"><div><b>3</b><span>adult-supported rounds</span></div><div><b>${s.independent}</b><span>rounds without extra hints or retries</span></div></div><p class="micro">Every round included adult support. This is practice, not an independent assessment.</p><div class="game-controls"><button class="secondary" id="adultAgain">Play again together</button><button class="primary" id="adultContinue">${s.index<19?'Next game with an adult →':'Back to the course →'}</button></div><div class="learning-note"><b>Try it with real objects.</b> ${d.exercise}</div>`);document.querySelector('#adultAgain').onclick=()=>adultIntro(s.index);document.querySelector('#adultContinue').onclick=()=>s.index<19?adultIntro(s.index+1):renderLearningCourse();}
